from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)


def test_parse_transcript_log_flag_values_and_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", "b, -2, 0", " c , 3 , \t"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_lines_and_comments():
    lines = ["", " \t\n", "# comment", " \t# ignored,even,with,commas", "x#1,2,0"]
    assert parse_transcript_log(lines) == [{"id": "x#1", "day": 2, "flagged": False}]
    assert parse_transcript_log(lines[:-1]) == []
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    lines = ["", " # comment", "valid,1,1", " \t", bad_line]
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(lines)


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    original = {"id": "a", "day": 0, "flagged": True}
    replacement = {"id": "a", "day": 3, "flagged": None}
    b = {"id": "b", "day": 3, "flagged": False}
    c = {"id": "c", "day": 1, "flagged": True}
    events = [original, b, c, replacement]
    assert dedupe_transcripts(events) == [c, replacement, b]
    assert events == [original, b, c, replacement]
    assert dedupe_transcripts([]) == []


def test_dedupe_transcripts_last_input_record_not_latest_day():
    events = [
        {"id": "a", "day": 10, "flagged": True},
        {"id": "a", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[-1]]


def test_daily_flag_counts_inclusive_range_gaps_and_unflagged():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []


def test_daily_flag_counts_no_events():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 2, 1) == []
