from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_summary_pooled_rate_rounding_calendar_window_and_group_count():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [
            {"day": 2, "flagged": True},
            {"day": 4, "flagged": None},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 10)["recent"] == 2


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_rate_order_ties_and_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": None}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 3) == []
    assert top_flagged_groups({"empty": []}, 3) == []
